def transform(grid):
    """Recolor complete monochrome separator rows and columns as color 2."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    rows = [r for r in range(h) if len(set(out[r])) == 1]
    cols = [c for c in range(w) if all(out[r][c] == out[0][c] for r in range(h))]
    for r in rows:
        out[r] = [2] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out

